head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > enterKeyPanelToggle]<br/>Accordion 컴포넌트에서 Enter 키로 패널을 열고 닫을지 설정합니다.",
    "validation" : [
        "enterKeyPanelToggle=true 설정 시 setDisabledPanel() 메소드로 비활성화된 패널은 Enter 키로 열거나 닫을 수 없습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (enterKeyPanelToggle=true 고정)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        enterKeyPanelToggle : "true",
        collapsible : "true",
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* 시나리오 : panels1 disabled 버튼 클릭 → panelTitle1 포커스 버튼 클릭 → Enter 키 입력 → panels1 이 토글되지 않음 확인"', '', 'label1');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// panels1 패널 비활성화 (Enter 키 토글 차단 확인용)
scwin.btn_setPanels1Disabled_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== setDisabledPanel('panels1', true) 호출 =====");
    target1.setDisabledPanel("panels1", true);
    wf_body_bottom.getObj("scwin").setReturnValue("panels1 비활성화 완료 - panelTitle1 포커스 후 Enter 키 입력해도 토글되지 않아야 함");
};



// panelTitle1 영역에 포커스 (accessibility=true 면 a태그, false 면 div 에 tabindex 부여 후 포커스)
scwin.btn_focusPanelTitle1_onclick = function (e) {
    let titleEl = target1.render.querySelector("[id$='_panel_panels1_title']");
    if (titleEl) {
        let focusTarget = titleEl.querySelector("a") || titleEl;
        if (!focusTarget.hasAttribute("tabindex")) {
            focusTarget.setAttribute("tabindex", "0");
        }
        focusTarget.focus();
        wf_body_bottom.getObj("scwin").setReturnValue("===== panelTitle1 포커스 =====");
        wf_body_bottom.getObj("scwin").setReturnValue("focused tagName : " + document.activeElement.tagName);
        wf_body_bottom.getObj("scwin").setReturnValue("focused id : " + document.activeElement.id);
    }
};



// 현재 열린 패널 정보 출력 (Enter 키 토글 전/후 상태 확인용)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
